import { Component } from '@angular/core';
import { NzIconModule } from 'ng-zorro-antd/icon';
import { NzButtonModule } from 'ng-zorro-antd/button';
import { NzUploadFile, NzUploadModule } from 'ng-zorro-antd/upload';
import { NzImageModule } from 'ng-zorro-antd/image';
import { NzModalModule } from 'ng-zorro-antd/modal';
import { NzDrawerModule } from 'ng-zorro-antd/drawer';
import { NzModalService } from 'ng-zorro-antd/modal';
import { NzDrawerService } from 'ng-zorro-antd/drawer';
import { PdfViewerComponent } from '../../../shared/components/pdf-viewer/pdf-viewer.component'
import { FileDetailComponent } from '../../../shared/components/file-detail/file-detail.component'
import { DocumentInterface } from '../../../core/interfaces/document.interface';

@Component({
  selector: 'app-documents',
  imports: [
    NzIconModule,
    NzButtonModule,
    NzUploadModule,
    NzImageModule,
    NzModalModule,
    NzDrawerModule,
    PdfViewerComponent,
    FileDetailComponent
  ],
  templateUrl: './documents.component.html',
  styleUrl: './documents.component.scss'
})
export class DocumentsComponent {

  public fallback: string = 'data:image/png;base64,';
  public items: any = {};
  public fileList: NzUploadFile[] = [];

  constructor(
    private modal: NzModalService,
    private drawerService: NzDrawerService
  ) 
  { }

  ngOnInit(): void {
    this.items = {
      data: [
        {
          id: 1,
          path: "https://zos.alipayobjects.com/rmsportal/jkjgkEfvpUPVyRjUImniVslZfWPnJuuZ.png",
          name: "jkjgkEfvpUPVyRjUImniVslZfWPnJuuZ.png"
        },
        {
          id: 2,
          path: "https://images.pexels.com/photos/34306373/pexels-photo-34306373.jpeg",
          name: "pexels-photo-34306373.jpeg"
        },
        {
          id: 3,
          path: "https://zos.alipayobjects.com/rmsportal/jkjgkEfvpUPVyRjUImniVslZfWPnJuuY.png",
          name: "jkjgkEfvpUPVyRjUImniVslZfWPnJuuY.png"
        },
        {
          id: 4,
          path: "",
          name: "RMT_R_00001-00054076.pdf"
        }
      ]
    }

    this.items.data = this.items.data.map((item: any) => ({
      ...item,
      // Añadimos el prefijo MIME para hacerlo usable
      //path: this.addMimeType(item.data, item.name),
      normalizedPath: this.normalizePath(item)
    }));
  }

  public beforeUpload = (file: NzUploadFile): boolean => {
    // Leer el archivo como base64
    const reader = new FileReader();

    reader.onload = (e: ProgressEvent<FileReader>) => {
      const base64String = e.target?.result as string; // Ej: "data:application/pdf;base64,JVBERi0..."

      // Aquí puedes hacer lo que quieras con el base64:
      console.log('Archivo en base64:', base64String);

      this.items.data.push({
        id: this.items.data.length + 1,
        path: base64String, 
        name: file.name
      });
      
      // Si necesitas solo el contenido sin el prefijo:
      // const pureBase64 = base64String.split(',')[1];
    };
    
    reader.readAsDataURL(file as any); // FileReader espera un Blob/File
    
    this.fileList = this.fileList.concat(file);
    // Devuelve `false` para evitar que nz-upload intente subirlo
    return false;
  };

  public normalizePath(item: DocumentInterface): string {
    const { path, name } = item;

    // Caso 1: Ya es una data URL (tiene prefijo MIME)
    if (path.startsWith('') && path.includes(';base64,')) {
      return path;
    }

    // Caso 2: Parece una URL (empieza con http, https, /, etc.)
    if (
      path.startsWith('http://') ||
      path.startsWith('https://') ||
      path.startsWith('/') ||
      path.startsWith('./') ||
      path.startsWith('../')
    ) {
      return path; // lo dejamos como URL
    }

    // Caso 3: Es base64 SIN prefijo → lo convertimos a data URL
    if (name) {
      return this.addMimeType(path, name);
    }

    // Caso 4: No sabemos qué es → asumimos binario genérico
    return `application/octet-stream;base64,${path}`;
  }

  // Función para añadir el MIME type
  private addMimeType(base64: string, name?: string): string {
    // Si no hay fileName, usamos un tipo genérico
    if (!name) {
      return `application/octet-stream;base64,${base64}`;
    }

    const ext = name.split('.').pop()?.toLowerCase() || '';
    const mimeMap: Record<string, string> = {
      pdf: 'application/pdf',
      png: 'image/png',
      jpg: 'image/jpeg',
      jpeg: 'image/jpeg',
      gif: 'image/gif',
      docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      doc: 'application/msword',
      xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      xls: 'application/vnd.ms-excel'
    };
    const mime = mimeMap[ext] || 'application/octet-stream';
    return `${mime};base64,${base64}`;
  }

  public getFileType(item: DocumentInterface): 'image' | 'pdf' | 'doc' | 'xls' | 'other' {
    const normalizedPath = this.normalizePath(item);

    // Función auxiliar para detectar tipo por extensión
    const getTypeFromExtension = (str: string): 'image' | 'pdf' | 'doc' | 'xls' | 'other' => {
      const lower = str.toLowerCase();
      if (lower.endsWith('.pdf')) return 'pdf';
      if (/\.(jpg|jpeg|png|gif)$/i.test(lower)) return 'image';
      if (/\.(doc|docx)$/i.test(lower)) return 'doc';
      if (/\.(xls|xlsx)$/i.test(lower)) return 'xls';
      return 'other';
    };

    // Si NO es una data URL (es una URL externa o relativa)
    if (normalizedPath.startsWith('')) {
      // 1. Intenta con name
      if (item.name) {
        const typeFromName = getTypeFromExtension(item.name);
        if (typeFromName !== 'other') return typeFromName;
      }

      // 2. Si no hay name o no se detectó, intenta con la URL misma
      const typeFromUrl = getTypeFromExtension(normalizedPath);
      return typeFromUrl;
    }

    // Si ES una data URL, usamos el prefijo MIME
    if (normalizedPath.startsWith('image/')) return 'image';
    if (normalizedPath.startsWith('application/pdf')) return 'pdf';
    if (normalizedPath.includes('wordprocessingml')) return 'doc';
    if (normalizedPath.includes('spreadsheetml')) return 'xls';

    return 'other';
  }

  public openPdfPreview(item: DocumentInterface): void {
    let url = this.normalizePath(item);

    // Si es una URL externa, podrías usar iframe
    if (!url.startsWith('')) {
      // Usa iframe con la URL directa
      this.modal.create({
        nzTitle: 'PDF',
        nzContent: `<iframe src="${url}" width="100%" height="600px" style="border: none;"></iframe>`,
        nzWidth: '80%',
        nzFooter: null
      });
      return;
    }

    if (!url.startsWith('data:')) {
      url = `data:${url}`
    }

    // Si es base64, usa el componente PdfViewer
    this.modal.create({
      nzTitle: 'Vista previa del PDF',
      nzContent: PdfViewerComponent,
      nzData: { base64Data: url },
      nzWidth: '80%',
      nzFooter: null
    });
  }

  public openDocPreview(url: string): void {
    const googleViewerUrl = `https://docs.google.com/gview?url=${encodeURIComponent(url)}&embedded=true`;
    window.open(googleViewerUrl, '_blank');
  }

  public downloadFile(item: DocumentInterface): void {
    const link = document.createElement('a');
    link.href = item.path; // debe ser data URL válida
    link.download = item.name || 'documento';
    link.click();
  }

  public viewFile(item: DocumentInterface): void {
    this.drawerService.create({
      nzTitle: 'Detalles del archivo',
      nzContent: FileDetailComponent,
      nzData: item,
      nzWidth: '700px'
    });
  }
}
